import json
from fractions import Fraction
from math import gcd

# Target projection matrix P = [[p11, p12], [p21, p22]] with exact entries.
P = [
    [Fraction(1, 50), Fraction(7, 50)],
    [Fraction(7, 50), Fraction(49, 50)],
]

# Projection onto the line spanned by (a, b) is (1/(a^2+b^2)) * [[a^2, ab], [ab, b^2]].
# Enumerate integer direction vectors in a bounded box and keep exact matches.
matches = []
checked = 0
for a in range(1, 201):          # a > 0 is required by the problem
    for b in range(-200, 201):
        if gcd(abs(a), abs(b)) != 1:
            continue
        checked += 1
        n = a * a + b * b
        Q = [
            [Fraction(a * a, n), Fraction(a * b, n)],
            [Fraction(a * b, n), Fraction(b * b, n)],
        ]
        if Q == P:
            matches.append((a, b))

if len(matches) == 1:
    a, b = matches[0]
    final_answer = "\\begin{pmatrix} %d \\\\ %d \\end{pmatrix}" % (a, b)
    result = {
        "final_answer": final_answer,
        "evidence": {
            "method": "exhaustive enumeration of primitive integer directions with exact Fractions",
            "search_box": "a in [1,200], b in [-200,200], gcd(|a|,|b|)=1",
            "candidates_checked": checked,
            "matches": [list(m) for m in matches],
            "projection_formula": "(1/(a^2+b^2)) [[a^2, ab],[ab, b^2]]",
        },
    }
else:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {
            "candidates_checked": checked,
            "matches": [list(m) for m in matches],
        },
    }

print(json.dumps(result))
