import math
from fractions import Fraction

# Target: 4 sin x sin(60°-x) sin(60°+x); submitted: sin x (2 cos 2x + 1)

def target(x):
    r60 = math.radians(60)
    return 4 * math.sin(x) * math.sin(r60 - x) * math.sin(r60 + x)

def submitted(x):
    return math.sin(x) * (2 * math.cos(2 * x) + 1)

def sin3x(x):
    return math.sin(3 * x)

# 1) Numerical sampling (supports, does not prove, the identity)
max_err_sub = 0.0
max_err_s3 = 0.0
count = 0
for k in range(-7200, 7201):          # steps of 0.1 degree over [-720°, 720°]
    x = math.radians(k / 10.0)
    t = target(x)
    max_err_sub = max(max_err_sub, abs(t - submitted(x)))
    max_err_s3 = max(max_err_s3, abs(t - sin3x(x)))
    count += 1

print("sampled points:", count)
print("max |target - submitted| over samples:", max_err_sub)
print("max |target - sin(3x)| over samples:", max_err_s3)

# 2) Exact algebraic proof in s = sin x (polynomials with Fraction coefficients)
# Identity used: sin(60-x)sin(60+x) = sin^2(60) - sin^2(x), with sin^2(60) = 3/4.
# Verify that identity numerically at sample points.
r60 = math.radians(60)
id_err = 0.0
for k in range(-3600, 3601):
    x = math.radians(k / 10.0)
    lhs_p = math.sin(r60 - x) * math.sin(r60 + x)
    rhs_p = math.sin(r60) ** 2 - math.sin(x) ** 2
    id_err = max(id_err, abs(lhs_p - rhs_p))
print("max error of product identity sin(60-x)sin(60+x)=sin^2(60)-sin^2(x):", id_err)

def poly_mul(p, q):
    out = {}
    for i, a in p.items():
        for j, b in q.items():
            out[i + j] = out.get(i + j, Fraction(0)) + a * b
    return {k: v for k, v in out.items() if v != 0}

def poly_add(p, q):
    out = dict(p)
    for k, v in q.items():
        out[k] = out.get(k, Fraction(0)) + v
    return {k: v for k, v in out.items() if v != 0}

# Target as polynomial in s: 4s * (3/4 - s^2)
inner_target = {0: Fraction(3, 4), 2: Fraction(-1)}
target_poly = poly_mul({1: Fraction(4)}, inner_target)

# Submitted as polynomial in s: cos 2x = 1 - 2s^2, so s * (2(1 - 2s^2) + 1)
cos2x_poly = {0: Fraction(1), 2: Fraction(-2)}
submitted_poly = poly_mul({1: Fraction(1)}, poly_add(poly_mul({0: Fraction(2)}, cos2x_poly), {0: Fraction(1)}))

# sin(3x) = 3s - 4s^3
sin3x_poly = {1: Fraction(3), 3: Fraction(-4)}

print("target polynomial in s:", dict(sorted(target_poly.items())))
print("submitted polynomial in s:", dict(sorted(submitted_poly.items())))
print("sin(3x) polynomial in s:", dict(sorted(sin3x_poly.items())))

exact_match = (target_poly == submitted_poly) and (target_poly == sin3x_poly)
print("exact polynomial identity holds:", exact_match)

if exact_match and max_err_sub < 1e-9 and id_err < 1e-12:
    print("Simplified form: sin(3x); submitted answer equals it.")
    print("CHECK PASS")
else:
    print("CHECK FAIL")
